with dim_totals as (select d.status, e.txn_type, count(*) as num_rows, sum(e.amount) as total_amount from transactions e inner join accounts d on e.account_id = d.id group by d.status, e.txn_type) select status, txn_type, num_rows, total_amount, case when txn_type rlike '^(DEBIT|FEE)$' then 'CORE' else 'PRIORITY' end as txn_type_zone from dim_totals order by status asc nulls last, num_rows asc
